/* ---------- IndexedDB (on-device only) ---------- */
const DB={db:null,open(){return new Promise((ok,no)=>{const r=indexedDB.open('supervisor-dashboard',1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('kv');d.createObjectStore('snaps',{keyPath:'t'})};r.onsuccess=()=>{this.db=r.result;ok()};r.onerror=()=>no(r.error)})},
 tx(st,m='readonly'){return this.db.transaction(st,m).objectStore(st)},
 get(k){return new Promise(ok=>{const r=this.tx('kv').get(k);r.onsuccess=()=>ok(r.result);r.onerror=()=>ok(null)})},
 set(k,v){return new Promise((ok,no)=>{const r=this.tx('kv','readwrite').put(v,k);r.onsuccess=()=>ok();r.onerror=()=>no(r.error)})},
 snaps(){return new Promise(ok=>{const r=this.tx('snaps').getAll();r.onsuccess=()=>ok(r.result||[]);r.onerror=()=>ok([])})},
 addSnap(s){return new Promise(ok=>{const t=this.tx('snaps','readwrite');t.put(s);t.transaction.oncomplete=ok})},
 delSnap(k){return new Promise(ok=>{const t=this.tx('snaps','readwrite');t.delete(k);t.transaction.oncomplete=ok})}};
let saveT=null;
function save(){const i=$('#saveInd');i.textContent='… جارٍ الحفظ';i.classList.add('saving');clearTimeout(saveT);saveT=setTimeout(async()=>{try{await DB.set('state',S);i.textContent='✓ محفوظ';i.classList.remove('saving');autoSnap()}catch(e){i.textContent='⚠️ تعذّر الحفظ';toast('تعذّر الحفظ: '+e.message)}},350)}
async function autoSnap(force){if(!S.settings.autoBackup&&!force)return;const now=Date.now();if(!force&&now-(S.settings.lastSnap||0)<6*3600e3)return;
 S.settings.lastSnap=now;await DB.addSnap({t:now,data:JSON.parse(JSON.stringify(S))});const all=(await DB.snaps()).sort((a,b)=>b.t-a.t);for(const x of all.slice(10))await DB.delSnap(x.t);await DB.set('state',S)}
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('on');clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('on'),2800)}
/* ---------- Hijri (Umm al-Qura via Intl, offline) ---------- */
const HF=new Intl.DateTimeFormat('en-u-ca-islamic-umalqura-nu-latn',{day:'numeric',month:'numeric',year:'numeric',timeZone:'Asia/Riyadh'});
function toH(dt){const p=HF.formatToParts(dt),g=t=>parseInt((p.find(x=>x.type===t)||{}).value);return{y:g('year')||g('relatedYear'),m:g('month'),d:g('day')}}
const H2G=new Map();(function(){const s=new Date(Date.UTC(2025,5,1,9));for(let i=0;i<1100;i++){const d=new Date(s.getTime()+i*864e5),h=toH(d);H2G.set(h.y+'-'+h.m+'-'+h.d,d)}})();
function hToG(y,m,d){return H2G.get(y+'-'+m+'-'+d)||null}
const hs=h=>h?`${h.d}/${h.m}/${h.y}`:'';
const GF=new Intl.DateTimeFormat('ar-SA-u-ca-gregory-nu-latn',{day:'numeric',month:'short',timeZone:'Asia/Riyadh'});
function weekDays(w){const st=hToG(S.year,w.m,w.d);if(!st)return DAYS.map((n,i)=>({name:n,h:null,g:null}));return DAYS.map((n,i)=>{const g=new Date(st.getTime()+i*864e5);return{name:n,g,h:toH(g)}})}
function weekLabel(w){const ds=weekDays(w);return`الأسبوع ${AR(w.n)} (${ORD[w.n]||w.n}) · ${ds[0].h?AR(hs(ds[0].h)):''} – ${ds[4].h?AR(hs(ds[4].h)):''}`}
function currentWeek(){const t=new Date();let best=null;for(const w of S.weeks){const ds=weekDays(w);if(!ds[0].g)continue;const s=ds[0].g.getTime()-864e5*1.5,e=ds[4].g.getTime()+864e5*1.6;if(t>=s&&t<=e)return w.n;if(t>e)best=w.n}return best||(S.weeks[0]||{}).n||1}
let WK=null;const getW=n=>S.weeks.find(w=>w.n==n)||S.weeks[0];
/* ---------- helpers ---------- */
const num=v=>{if(v===''||v==null)return null;const n=Number(String(v).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[^\d.\-]/g,''));return isFinite(n)&&String(v).trim()!==''?n:null};
const pct=(a,b)=>(a==null||b==null||b==='')?null:(b==0?0:a/b);
const fp=(x,d=1)=>x==null||isNaN(x)?'—':(Math.round(x*100*Math.pow(10,d))/Math.pow(10,d))+'%';
const r1=(x,d=1)=>x==null||isNaN(x)?'—':Math.round(x*Math.pow(10,d))/Math.pow(10,d);
const avg=a=>{a=a.filter(x=>x!=null&&!isNaN(x));return a.length?a.reduce((s,x)=>s+x,0)/a.length:null};
const median=a=>{a=a.filter(x=>x!=null).sort((x,y)=>x-y);if(!a.length)return null;const m=a.length>>1;return a.length%2?a[m]:(a[m-1]+a[m])/2};
const stdev=a=>{a=a.filter(x=>x!=null);if(a.length<2)return null;const m=avg(a);return Math.sqrt(a.reduce((s,x)=>s+(x-m)**2,0)/(a.length-1))};
const sName=id=>{const s=S.schools.find(x=>x.id===id);return s?s.name:'—'};
const schoolsSorted=()=>[...S.schools].sort((a,b)=>(a.order||0)-(b.order||0));
const key=(w,d,sid)=>w+'|'+d+'|'+sid;
function loginCell(w,d,s){const r=S.logins[key(w,d,s.id)]||{};const tT=r.tT??num(s.teachers),sT=r.sT??num(s.students);return{...r,tT,sT,tp:r.hol?null:pct(r.t,tT),sp:r.hol?null:pct(r.s,sT)}}
function absCell(w,d,s){const r=S.absences[key(w,d,s.id)]||{};const n=r.n??num(s.students);return{...r,n,p:r.hol?null:pct(r.a,n)}}
function weekLoginAvg(w,s){const t=[],st=[];for(let d=0;d<5;d++){const c=loginCell(w,d,s);if(c.tp!=null)t.push(c.tp);if(c.sp!=null)st.push(c.sp)}return{t:avg(t),s:avg(st)}}
function weekAbsAvg(w,s){const a=[];for(let d=0;d<5;d++){const c=absCell(w,d,s);if(c.p!=null)a.push(c.p)}return avg(a)}
function visitMonth(v){const m=String(v.hijri||'').split('/');if(m.length>=2&&num(m[1]))return num(m[1]);const w=getW(v.week);if(w&&v.day!=null){const d=weekDays(w)[v.day];if(d&&d.h)return d.h.m}return 0}
function visitDate(v){if(v.hijri)return v.hijri;const w=getW(v.week);const d=w&&weekDays(w)[v.day];return d&&d.h?hs(d.h):''}
const realVisits=()=>S.visits.filter(v=>v.schoolId);
function help(title,items){return`<details class="help"><summary>💡 تعليمات الاستخدام — ${esc(title)}</summary><ul>${items.map(i=>`<li>${i}</li>`).join('')}</ul></details>`}
function printHead(t){return`<div class="print-only" style="text-align:center;margin-bottom:8px"><div style="font-weight:800">وزارة التعليم | المملكة العربية السعودية</div><div>${esc(S.settings.sector||'الفريق التنفيذي')}</div><div style="font-weight:800;font-size:15px;color:#0f2747">${esc(t)}</div><div>${S.settings.member?'عضو الفريق التنفيذي: '+esc(S.settings.member)+' | ':''}العام الدراسي ${AR(S.year)}هـ</div></div>`}
function head(t,sub,acts=''){return`<div class="head"><div><h2>${t}</h2>${sub?`<div class="muted small">${sub}</div>`:''}</div><div class="acts">${acts}<button class="btn ghost sm" data-act="print">🖨️ طباعة / PDF</button></div></div>`+printHead(t.replace(/<[^>]+>/g,'').replace(/^\S+\s/,''))}
const stCls=s=>s==='منجز'?'ok':s==='قيد التنفيذ'?'warn':s==='لم تُنجز'?'red':'';
const normSt=s=>{s=String(s||'').trim();if(!s)return'';if(/^منجز/.test(s))return'منجز';if(/قيد/.test(s))return'قيد التنفيذ';if(/لم/.test(s))return'لم تُنجز';return s};
/* ---------- SVG charts (no external libs) ---------- */
const PAL=['#0f2747','#c9a227','#b91c1c','#15803d','#1d4ed8','#7c3aed','#0891b2','#b45309','#be185d','#4d7c0f'];
function legend(series){return`<div class="legend">${series.map((s,i)=>`<span><i style="background:${s.color||PAL[i%PAL.length]}"></i>${esc(s.name)}</span>`).join('')}</div>`}
function barChart(labels,series,{max=null,isPct=true,h=260,title=''}={}){
 const W=Math.max(560,labels.length*series.length*22+120),H=h,pl=44,pr=10,pt=20,pb=70,cw=W-pl-pr,ch=H-pt-pb;
 let mx=max??Math.max(0.0001,...series.flatMap(s=>s.values.map(v=>v||0)));if(isPct&&max==null)mx=Math.min(1,Math.max(mx*1.15,0.05));if(!isPct&&max==null)mx=Math.ceil(mx*1.15)||1;
 const gw=cw/Math.max(1,labels.length),bw=Math.min(28,(gw-8)/series.length);let g='';
 for(let i=0;i<=4;i++){const y=pt+ch-ch*i/4,v=mx*i/4;g+=`<line x1="${pl}" x2="${W-pr}" y1="${y}" y2="${y}" stroke="#9ca3af" stroke-opacity=".3"/><text x="${pl-4}" y="${y+4}" font-size="10" text-anchor="end">${isPct?Math.round(v*100)+'%':Math.round(v*10)/10}</text>`}
 labels.forEach((l,i)=>{const x0=W-pr-gw*(i+1)+(gw-bw*series.length)/2;series.forEach((s,j)=>{const v=s.values[i];if(v==null)return;const bh=Math.max(0,ch*Math.min(v,mx)/mx),x=x0+j*bw,y=pt+ch-bh;
  g+=`<rect x="${x}" y="${y}" width="${bw-2}" height="${bh}" rx="3" fill="${s.color||PAL[j%PAL.length]}"><title>${esc(s.name)} — ${esc(l)}: ${isPct?fp(v):v}</title></rect>`;if(series.length<=3&&labels.length<=12)g+=`<text x="${x+bw/2-1}" y="${y-3}" font-size="9" text-anchor="middle">${isPct?Math.round(v*1000)/10+'%':v}</text>`});
  const lx=W-pr-gw*(i+0.5);g+=`<text x="${lx}" y="${pt+ch+14}" font-size="10" text-anchor="end" transform="rotate(-35 ${lx} ${pt+ch+14})">${esc(String(l).slice(0,26))}</text>`});
 return`<div class="chart" role="img" aria-label="${esc(title)}"><svg viewBox="0 0 ${W} ${H}">${g}</svg></div>${series.length>1||series[0].name?legend(series):''}`}
function lineChart(labels,series,{isPct=true,h=260,title='',max=null}={}){
 const W=Math.max(560,labels.length*46+80),H=h,pl=44,pr=16,pt=16,pb=56,cw=W-pl-pr,ch=H-pt-pb;
 let mx=max??Math.max(0.0001,...series.flatMap(s=>s.values.map(v=>v||0)));if(isPct&&max==null)mx=Math.min(1,Math.max(mx*1.15,0.05));if(!isPct&&max==null)mx=Math.ceil(mx*1.15)||1;
 const X=i=>labels.length<2?W-pr-cw/2:W-pr-cw*i/(labels.length-1),Y=v=>pt+ch-ch*Math.min(v,mx)/mx;let g='';
 for(let i=0;i<=4;i++){const y=pt+ch-ch*i/4,v=mx*i/4;g+=`<line x1="${pl}" x2="${W-pr}" y1="${y}" y2="${y}" stroke="#9ca3af" stroke-opacity=".3"/><text x="${pl-4}" y="${y+4}" font-size="10" text-anchor="end">${isPct?Math.round(v*100)+'%':Math.round(v)}</text>`}
 labels.forEach((l,i)=>{g+=`<text x="${X(i)}" y="${pt+ch+14}" font-size="10" text-anchor="end" transform="rotate(-30 ${X(i)} ${pt+ch+14})">${esc(l)}</text>`});
 series.forEach((s,j)=>{const c=s.color||PAL[j%PAL.length];let d='',pts='';s.values.forEach((v,i)=>{if(v==null)return;d+=(d?'L':'M')+X(i)+' '+Y(v);pts+=`<circle cx="${X(i)}" cy="${Y(v)}" r="3.5" fill="${c}"><title>${esc(s.name)} — ${esc(labels[i])}: ${isPct?fp(v):v}</title></circle>`});g+=`<path d="${d}" fill="none" stroke="${c}" stroke-width="2.5"${s.dash?' stroke-dasharray="6 4"':''}/>${pts}`});
 return`<div class="chart" role="img" aria-label="${esc(title)}"><svg viewBox="0 0 ${W} ${H}">${g}</svg></div>${legend(series)}`}
/* ---------- computed KPIs (same formulas as the workbook) ---------- */
function controlKPIs(){const T=S.schools.map(s=>num(s.teachers)).filter(x=>x!=null);const sum=T.reduce((a,b)=>a+b,0);
 return{schools:S.schools.length,teachers:sum,avg:T.length?Math.round(avg(T)*10)/10:0,avg2:T.length?Math.round(avg(T)*100)/100:0,max:T.length?Math.max(...T):0,min:T.length?Math.min(...T):0,median:T.length?Math.round(median(T)*100)/100:0,sd:T.length>1?Math.round(stdev(T)*100)/100:0}}
function taskStats(cat){const L=S.tasks.filter(t=>!cat||t.cat===cat);const c=st=>L.filter(t=>normSt(t.status)===st).length;const total=L.length,done=c('منجز');
 return{total,filled:L.filter(t=>t.status).length,done,doing:c('قيد التنفيذ'),not:c('لم تُنجز'),pct:total?Math.round(done/total*1000)/10:0}}
function weekSummary(wn){const out={t:[],s:[],a:[],low:[],high:[]};for(const s of schoolsSorted()){const l=weekLoginAvg(wn,s),a=weekAbsAvg(wn,s);if(l.t!=null)out.t.push(l.t);if(l.s!=null)out.s.push(l.s);if(a!=null)out.a.push(a);
 const lm=S.settings.loginMin/100,am=S.settings.absMax/100;if(l.t!=null&&l.t<lm)out.low.push([s,'المعلمين',l.t]);if(l.s!=null&&l.s<lm)out.low.push([s,'الطلاب',l.s]);if(a!=null&&a>am)out.high.push([s,a])}
 return{...out,tAvg:avg(out.t),sAvg:avg(out.s),aAvg:avg(out.a),visits:realVisits().filter(v=>v.week==wn)}}
