 const byW=S.weeks.map(w=>[w.n,V2.filter(v=>v.week==w.n).length]);const byS=schoolsSorted().map(s=>[s,V2.filter(v=>v.schoolId===s.id).length]);const byF=VFIELDS.map(f=>[f,V2.filter(v=>v.field===f).length]);
