function loadSample(){const D=blank();D.settings={...S.settings,sample:true,member:'عضو فريق تجريبي',sector:'الفريق التنفيذي (بيانات تجريبية)'};let seed=7;const R=()=>(seed=(seed*16807)%2147483647)/2147483647;
 const nm=[['مدرسة النخيل','الابتدائية'],['مدرسة الريان','المتوسطة'],['مدرسة الواحة','الثانوية'],['مدرسة السلام','الابتدائية'],['مدرسة الفجر','المتوسطة'],['مدرسة الضياء','الثانوية']];
 D.schools=nm.map((x,i)=>({id:'demo'+i,order:i+1,name:`${x[0]} ${x[1]} (تجريبي)`,stage:x[1],ministryNo:'00000'+(i+1),gender:'بنين',principal:`مدير تجريبي ${i+1}`,principalMobile:'050000000'+(i+1),deputy:`وكيل تجريبي ${i+1}`,deputyMobile:'050000001'+(i+1),
  teachers:[9,12,15,11,14,17][i],students:[60,85,110,70,95,130][i],specialties:i%3?'نعم':'عجز (تجريبي)',teacherLogin:'تم',studentLogin:i%2?'يحتاج متابعة':'تم',result:['جيد جداً','جيد','ممتاز','جيد','مقبول',''][i],healthGuide:'يوجد',studentGuide:i===4?'لايوجد':'يوجد',centralExams:i%2?'تم':'غير مشمول',schoolPlan:'نعم',principalWork:'نعم',improve:i===1||i===3?'نعم':'',interventionPlan:i===1||i===3?'نعم':'',diagnostic:i===1||i===3?'نعم':''}));
 const cw=currentWeek();for(let w=1;w<=cw;w++)for(let d=0;d<5;d++){const hol=w===5&&d>=3;D.schools.forEach((s,i)=>{const k=key(w,d,s.id);if(hol){D.logins[k]={hol:true};D.absences[k]={hol:true};return}
  const tr=Math.min(1,.8+R()*.22),sr=Math.min(.95,.12+w*.06+R()*.12-(i===4?.12:0));D.logins[k]={t:Math.round(s.teachers*tr),s:Math.max(0,Math.round(s.students*sr))};D.absences[k]={a:Math.round(s.students*(R()*.05+(i===2&&w===cw?.06:0)))}})}
 const fl=VFIELDS;for(let w=1;w<=cw;w++)for(let d=0;d<5;d++){if(w===5&&d>=3){D.visits.push({id:uid(),week:w,day:d,hijri:'',schoolId:'',type:'',field:'',notes:'إجازة (تجريبي)'});continue}if(w<cw&&R()<.12)continue;const s=D.schools[(w*5+d)%6];D.visits.push({id:uid(),week:w,day:d,hijri:'',schoolId:s.id,type:R()<.85?'حضوري':'عن بعد',field:fl[Math.floor(R()*5)],notes:'ملاحظة تجريبية'})}
 D.tasks.forEach((t,i)=>{t.status=TASK_ST[[0,0,1,0,0,2,0,0,0,2,1,0][i]];t.lastDate=''});
 S=D;WK=cw;suggest(cw);S.reports[cw].s4='نص تجريبي: تم التأكد من تطبيق الجدول الدراسي المعتمد.';S.reports[cw].s5='نص تجريبي للتوضيح فقط.';S.reports[cw].s6='نص تجريبي للتوضيح فقط.';save();render();toast('🧪 تم تحميل بيانات تجريبية وهمية')}
